import 'dart:convert';
import 'chat_help_catalog.dart';
import 'chat_interpretation.dart';
import 'chat_plan_constraints.dart';
import 'chat_scope_delta.dart';

/// Model-independent boundary: operands are literal quotes, never SQL, dates
/// generated by the model, computed values, or transaction records.
class ChatRequestContract {
  static const sources = ['transactions', 'accounts', 'goals', 'budgets'];
  static const metrics = ['sum', 'count', 'avg', 'min', 'max', 'list'];
  static const groups = [
    'none',
    'category',
    'merchant',
    'both',
    'day',
    'weekday',
    'month',
    'year',
    'account',
  ];
  static const purposes = [
    'records',
    'help',
    'social',
    'advice',
    'safety',
    'unrelated',
    'clarify',
  ];
  // Clarification is a compiler/help-resolution outcome, not an escape route
  // for a classifier that has not seen the user's database or resolved dates.
  static const routes = [
    'records',
    'help',
    'social',
    'advice',
    'safety',
    'unrelated',
  ];
  static const reasons = [
    'question',
    'period',
    'type',
    'merchant',
    'category',
    'feature',
    'benchmark',
  ];
  static Map<String, dynamic> _enum(List<String> values) => {
    'type': 'string',
    'enum': values,
  };
  static Map<String, dynamic> get schema => {
    'type': 'object',
    'properties': {
      'purpose': _enum(purposes),
      'query': {
        'type': 'object',
        'properties': {
          'source': _enum(sources),
          'metric': _enum(metrics),
          'type': _enum(['expense', 'income']),
          'group': _enum(groups),
          'scope': _enum(['new', 'followup']),
          for (final key in ['merchant', 'category', 'account'])
            key: {'type': 'string', 'minLength': 1, 'maxLength': 100},
        },
        'required': ['source', 'metric', 'type', 'group', 'scope'],
        'additionalProperties': false,
      },
      'topic': _enum(ChatHelpCatalog.instructions.keys.toList()),
      'reason': _enum(reasons),
    },
    'required': ['purpose'],
    'additionalProperties': false,
  };

  /// Literal constraints narrow fields, never the purpose or financial answer.
  /// Unrecognized language keeps the full enum for semantic interpretation.
  static Map<String, dynamic> schemaFor(
    String question, {
    Map<String, dynamic>? context,
  }) {
    final result = schema;
    final fields = result['properties']['query']['properties'] as Map;
    for (final (field, value) in [
      ('source', ChatPlanConstraints.source(question)),
      ('metric', ChatPlanConstraints.metric(question)),
      ('type', ChatPlanConstraints.type(question)),
      ('group', ChatPlanConstraints.group(question)),
    ]) {
      if (value != null) fields[field] = _enum([value]);
    }
    final prior = context?['queries'];
    if (context != null &&
        (context['force_followup'] == true ||
            ChatPlanConstraints.hasScopeReference(question))) {
      fields['scope'] = _enum(['followup']);
    } else if (!ChatPlanConstraints.usesQueryContext(question)) {
      fields['scope'] = _enum(['new']);
    }
    if (ChatScopeDelta.periodOnly(question) &&
        prior is List &&
        prior.isNotEmpty &&
        prior.every((q) => q is Map)) {
      for (final (key, fallback) in [
        ('source', 'transactions'),
        ('metric', 'sum'),
        ('type', 'expense'),
      ]) {
        final values = prior.map((q) => q[key] ?? fallback).toSet();
        if (values.length == 1 && values.single is String) {
          fields[key] = _enum([values.single as String]);
        }
      }
      final grouping = prior.map((q) => q['group'] ?? 'none').toSet();
      if (grouping.length == 1) {
        fields['group'] = _enum([grouping.single as String]);
      }
      if (grouping.length == 2 &&
          grouping.containsAll(['category', 'merchant'])) {
        fields['group'] = _enum(['both']);
      }
      fields['scope'] = _enum(['followup']);
    }
    return result;
  }

  /// Each action carries its required operands. A records decision without a
  /// query cannot be emitted as a syntactically valid action.
  static Map<String, dynamic> actionSchemaFor(
    String question, {
    Map<String, dynamic>? context,
  }) {
    final properties =
        schemaFor(question, context: context)['properties'] as Map;
    Map<String, dynamic> branch(String purpose, [String? operand]) => {
      'type': 'object',
      'properties': {
        'purpose': _enum([purpose]),
        if (operand != null) operand: properties[operand],
      },
      'required': ['purpose', if (operand != null) operand],
      'additionalProperties': false,
    };
    if (context != null && ChatScopeDelta.periodOnly(question)) {
      return {
        'oneOf': [branch('records', 'query')],
      };
    }
    final feature = ChatHelpCatalog.requestedTopic(question);
    if (feature != null) {
      final help = branch('help', 'topic');
      (help['properties'] as Map)['topic'] = _enum([feature]);
      return {
        'oneOf': [help],
      };
    }
    return {
      'oneOf': [
        branch('records', 'query'),
        branch('help', 'topic'),
        for (final purpose in routes.where(
          (p) => p != 'records' && p != 'help',
        ))
          branch(purpose),
      ],
    };
  }

  static ChatInterpretation decodeQuery(String raw, String message) {
    if (raw.length > 1000) throw const FormatException('Query too large');
    _rejectDuplicateKeys(raw);
    return decode(
      jsonEncode({'purpose': 'records', 'query': jsonDecode(raw)}),
      message,
    );
  }

  static ChatInterpretation decode(String raw, String message) {
    if (raw.length > 1600) {
      throw const FormatException('Interpretation too large');
    }
    _rejectDuplicateKeys(raw);
    final value = jsonDecode(raw);
    if (value is! Map<String, dynamic> ||
        value.keys.any(
          (k) => !{'purpose', 'query', 'topic', 'reason'}.contains(k),
        ) ||
        !purposes.contains(value['purpose'])) {
      throw const FormatException('Invalid request purpose');
    }
    final purpose = ChatPurpose.values.byName(value['purpose'] as String);
    if (purpose != ChatPurpose.records) {
      if (value.containsKey('query') ||
          value.containsKey('topic') && purpose != ChatPurpose.help ||
          value.containsKey('reason') && purpose != ChatPurpose.clarify) {
        throw const FormatException('Conflicting request fields');
      }
      if (purpose == ChatPurpose.help &&
          !ChatHelpCatalog.instructions.containsKey(value['topic'])) {
        throw const FormatException('Missing help topic');
      }
      if (purpose == ChatPurpose.clarify &&
          !reasons.contains(value['reason'])) {
        throw const FormatException('Missing clarification reason');
      }
      return ChatInterpretation.structured(
        purpose,
        purpose.name,
        topic: value['topic'] as String?,
        reason: value['reason'] as String?,
      );
    }
    if (value.length != 2 || value['query'] is! Map<String, dynamic>) {
      throw const FormatException('Missing record query');
    }
    final q = Map<String, dynamic>.from(value['query'] as Map);
    if (q.keys.any(
          (k) => !{
            'source',
            'metric',
            'type',
            'group',
            'scope',
            'merchant',
            'category',
            'account',
          }.contains(k),
        ) ||
        !sources.contains(q['source']) ||
        !metrics.contains(q['metric']) ||
        !groups.contains(q['group']) ||
        !['expense', 'income'].contains(q['type']) ||
        !['new', 'followup'].contains(q['scope'])) {
      throw const FormatException('Invalid record query');
    }
    for (final key in ['merchant', 'category', 'account']) {
      if (!q.containsKey(key)) continue;
      final text = q[key];
      if (text is! String ||
          text.trim().isEmpty ||
          text.length > 100 ||
          !_quoted(message, text)) {
        throw const FormatException('Ungrounded query operand');
      }
    }
    final op = ChatOperation(q['source'], q['metric'], q['group'], q['type']);
    return ChatInterpretation.structured(
      purpose,
      '${op.source}/${op.type}/${op.metric}/${op.group}',
      operation: op,
      query: Map.unmodifiable(q),
    );
  }

  static bool _quoted(String source, String text) {
    final escaped = RegExp.escape(
      text.trim(),
    ).replaceAll(RegExp(r'\s+'), r'\s+');
    return RegExp(
      '(?<![a-zA-Z0-9])$escaped(?![a-zA-Z0-9])',
      caseSensitive: false,
    ).hasMatch(source);
  }

  static void _rejectDuplicateKeys(String text) {
    final objects = <Set<String>>[];
    for (var i = 0; i < text.length; i++) {
      if (text[i] == '{') objects.add(<String>{});
      if (text[i] == '}' && objects.isNotEmpty) objects.removeLast();
      if (text[i] != '"') continue;
      final start = i++;
      while (i < text.length && text[i] != '"') {
        if (text[i] == r'\') i++;
        i++;
      }
      if (i >= text.length) throw const FormatException('Invalid JSON string');
      var next = i + 1;
      while (next < text.length && text[next].trim().isEmpty) {
        next++;
      }
      if (next < text.length &&
          text[next] == ':' &&
          objects.isNotEmpty &&
          !objects.last.add(
            jsonDecode(text.substring(start, i + 1)) as String,
          )) {
        throw const FormatException('Duplicate request field');
      }
    }
  }
}
